import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"共享、转让与清理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/sharing-transfer-cleanup.md","filePath":"guide/sharing-transfer-cleanup.md","lastUpdated":0}`),a={name:`guide/sharing-transfer-cleanup.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="共享、转让与清理" tabindex="-1">共享、转让与清理 <a class="header-anchor" href="#共享、转让与清理" aria-label="Permalink to “共享、转让与清理”">​</a></h1><h2 id="邮箱共享" tabindex="-1">邮箱共享 <a class="header-anchor" href="#邮箱共享" aria-label="Permalink to “邮箱共享”">​</a></h2><p>共享适合让另一位草丛 Mail 用户协助阅读邮箱。所有共享都是只读权限，不允许受邀人发信、修改邮箱设置、创建客户端密码、转让或删除邮箱。</p><p>所有者可以授权：</p><ul><li>整个邮箱。</li><li>指定系统文件夹。</li><li>指定自定义文件夹。</li><li>指定标签。</li></ul><p>共享创建成功后立即生效。接收方只能在获授权范围查看邮件列表、搜索结果、详情、会话、原文、附件和缩略图，并可从自己的共享列表中移除该共享。范围受限时，汇总数量也不会暴露未授权目录。所有者可查看阅读次数和最近阅读时间，修改范围、撤销单个共享或撤销整个邮箱的所有共享。</p><h2 id="创建共享" tabindex="-1">创建共享 <a class="header-anchor" href="#创建共享" aria-label="Permalink to “创建共享”">​</a></h2><p>创建共享时选择自己的邮箱和目标用户。自定义范围至少选一个文件夹或标签。当前版本采用直接授权：操作成功后接收方立即获得只读范围，无需另行接受；接收方可以随时移除。</p><p>共享用户应使用自己的账号登录，不能共用所有者密码。停止协作后立即撤销，并检查活动记录。</p><h2 id="邮箱转让" tabindex="-1">邮箱转让 <a class="header-anchor" href="#邮箱转让" aria-label="Permalink to “邮箱转让”">​</a></h2><p>转让把完整所有权交给另一位用户，与只读共享不同。发起方选择邮箱、接收方和转让类型，可附备注；接收方接受或拒绝，发起方可取消仍在等待的请求。</p><p>接受时系统重新核对邮箱归属、请求状态和接收方配额。并发操作冲突会安全失败，不会把邮箱交给错误用户。完成后原所有者不再有管理权限；如仍需查看，应由新所有者另行共享。</p><p>部分转让可能消耗 NodeLoc 能量。提交前确认页面显示的费用和余额，失败退款以能量流水为准。</p><h2 id="普通删除与彻底删除" tabindex="-1">普通删除与彻底删除 <a class="header-anchor" href="#普通删除与彻底删除" aria-label="Permalink to “普通删除与彻底删除”">​</a></h2><p>邮件普通删除通常进入已删除文件夹，可以在保留期内处理。彻底删除、清空邮箱或已经执行的清理任务无法通过网页恢复。</p><p>个人“邮件清理”页面只列出当前账号拥有的个人邮箱，不会把成员获分配或组织管理权限可见的企业邮箱纳入个人清理范围。企业邮箱应由组织管理流程处理，不能通过个人“全部粉碎”绕过组织权限。</p><p>清理中心按个人邮箱显示容量和可清理邮件，可以：</p><ul><li>安排延迟清理。</li><li>在执行前取消。</li><li>对特定待清理对象设置永久保留。</li><li>对选定邮件或邮箱执行明确的彻底清理。</li></ul><p>邮箱占用统计同时包含普通邮件、附件和隔离邮件，列表会单独显示隔离数量与占用。隔离邮件应优先到“被拦截邮件”逐封预览、放行或删除。</p><p>“全部粉碎”会删除所选个人邮箱所有系统文件夹和自定义文件夹中的邮件、对应附件以及隔离邮件；这不是只清理当前列表页或收件箱，也不会扩展到企业邮箱，完成后无法通过网页恢复。“待清理邮件”页面用于查看已经进入延迟队列的对象。执行前检查邮箱地址、范围、数量和时间；处理大量邮件时避免重复点击。</p><h2 id="所有权与配额" tabindex="-1">所有权与配额 <a class="header-anchor" href="#所有权与配额" aria-label="Permalink to “所有权与配额”">​</a></h2><p>共享邮件的存储仍计入原邮箱所有者或组织。邮箱转让后，存储和邮箱数量转到新所有者；系统在事务内检查接收方配额。清理释放的空间以后台任务真正完成后的存储统计为准。</p>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};